import pocketkit.*

func expectInvalid(catalog: TextCatalog, start: Int64, limit: Int64): Unit {
    var rejected = false
    try {
        catalog.window(start: start, limit: limit)
    } catch (e: IllegalArgumentException) {
        rejected = true
    }
    pocketkit.assert(rejected)
}

main(): Int64 {
    let catalog = TextCatalog(["a", "b", "c", "d"])

    let page: Array<?String> = catalog.window(start: 1, limit: 2)
    pocketkit.assert(page.size == 2)
    pocketkit.assert(page[0] == Some("b"))
    pocketkit.assert(page[1] == Some("c"))

    let defaultPage: Array<?String> = catalog.window()
    pocketkit.assert(defaultPage.size == 4)
    pocketkit.assert(defaultPage[0] == Some("a"))
    pocketkit.assert(defaultPage[1] == Some("b"))
    pocketkit.assert(defaultPage[2] == Some("c"))
    pocketkit.assert(defaultPage[3] == Some("d"))

    let endPage: Array<?String> = catalog.window(start: catalog.size)
    pocketkit.assert(endPage.size == 0)
    pocketkit.assert(catalog.window(start: 3, limit: 2).size == 1)
    pocketkit.assert(catalog.window(limit: 0).size == 0)

    expectInvalid(catalog, -1, 2)
    expectInvalid(catalog, catalog.size + 1, 2)
    expectInvalid(catalog, 0, -1)
    return 0
}

