answer.consumerCode:
import pocketkit.io.{openText, assert}

main(): Int64 {
    let reader = openText("first\nsecond")
    assert(!reader.closed)
    assert(reader.read() == Some("first"))
    assert(reader.read() == Some("second"))
    assert(reader.read() == None)
    assert(!reader.closed)

    reader.rewind()
    assert(!reader.closed)
    assert(reader.read() == Some("first"))
    assert(reader.read() == Some("second"))
    assert(reader.read() == None)

    reader.close()
    assert(reader.closed)
    reader.close()
    assert(reader.closed)

    var readFailed = false
    try {
        reader.read()
    } catch (e: IllegalStateException) {
        readFailed = true
    }
    assert(readFailed)

    var rewindFailed = false
    try {
        reader.rewind()
    } catch (e: IllegalStateException) {
        rewindFailed = true
    }
    assert(rewindFailed)
    assert(reader.closed)
    return 0
}

evidence.excerpt:
/**
 * 按换行符读取内存文本，显式展示资源责任。
 *
 * 构造时复制拆分后的行数组；调用方拥有此阅读会话。close 可重复调用，关闭后
 * read 和 rewind 抛出异常。没有文件描述符、网络连接或后台线程需要销毁。
